CREATE TABLE IF NOT EXISTS support_tickets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject VARCHAR(190) NOT NULL,category VARCHAR(20) NOT NULL DEFAULT 'general',priority VARCHAR(10) NOT NULL DEFAULT 'normal',status VARCHAR(12) NOT NULL DEFAULT 'open',assigned_admin_id BIGINT UNSIGNED NULL,last_reply_by VARCHAR(10) NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL,closed_at DATETIME NULL,INDEX ticket_status(status,updated_at),INDEX ticket_user(user_id,updated_at),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS support_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,admin_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX message_ticket(ticket_id,id),FOREIGN KEY(ticket_id) REFERENCES support_tickets(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_banners(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,subtitle VARCHAR(255) NOT NULL DEFAULT '',image_file VARCHAR(80) NULL,link_url VARCHAR(255) NULL,link_label VARCHAR(40) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1,starts_on DATE NULL,ends_on DATE NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX banner_active(active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,body VARCHAR(1000) NOT NULL,url VARCHAR(255) NULL,audience VARCHAR(20) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'queued',last_user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,sent_count INT UNSIGNED NOT NULL DEFAULT 0,total INT UNSIGNED NOT NULL DEFAULT 0,created_by_admin BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,finished_at DATETIME NULL,INDEX announce_status(status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
